/**
 * Lấy danh sách từ vựng HSK theo cấp độ và các bộ lọc
 */
export function getHskWordsByLevel(
  level: number,
  options?: {
    lesson?: number;
    limit?: number;
    shuffle?: boolean;
  }
): HskTypingWord[] {
  let list = HSK_TYPING_WORDS.filter((w) => w.hskLevel === level);

  if (options?.lesson && options.lesson > 0) {
    list = list.filter((w) => w.lessonNumber === options.lesson);
  }

  if (options?.shuffle) {
    list = [...list].sort(() => Math.random() - 0.5);
  }

  if (options?.limit && options.limit > 0) {
    list = list.slice(0, options.limit);
  }

  return list;
}

/**
 * Lấy danh sách các bài học hiện có của cấp HSK
 */
export function getHskLessonNumbers(level: number): number[] {
  const words = HSK_TYPING_WORDS.filter((w) => w.hskLevel === level);
  const lessons = Array.from(new Set(words.map((w) => w.lessonNumber))).sort((a, b) => a - b);
  return lessons;
}
